# Per-project topic clustering run status (ADR-051): the rebuildable
# operational read model behind the settings page. One row per project;
# folded from run_completed/run_failed events, never written directly.
#
# id:: KSUID (`topicrun_…`), generated by the repository on first upsert.
# lastRunOutcome:: completed | skipped | failed
# lastRunErrorUserActionable:: True when the customer can resolve the failure (credentials, quota).
# inProgressStartedAt:: Business time the in-progress run opened; bounds how long the read
#   model may report it as running (mirrors the process's stale-run guard).
# occurredAt:: Business time of the latest applied event.
# acceptedAt:: Event-log acceptance time. Together with lastEventId this is the cursor.
class TopicClusteringRunProjection < ApplicationRecord
  self.table_name = "TopicClusteringRunProjection"

  attribute :lastRunErrorUserActionable, default: false
  attribute :lastRunTracesProcessed, default: 0
  attribute :lastRunTopicsCount, default: 0
  attribute :lastRunSubtopicsCount, default: 0
  attribute :lastRunPages, default: 0
  attribute :inProgressTraces, default: 0
  attribute :inProgressPages, default: 0

  validates :projectId, presence: true, uniqueness: true
  validates :projectId, uniqueness: true
  validates :createdAt, presence: true
  validates :updatedAt, presence: true
  validates :occurredAt, presence: true
  validates :acceptedAt, presence: true
  validates :lastEventId, presence: true
  validates :projectionVersion, presence: true
end
